import math

def check_n(n):
    """
    Tests if for all k relatively prime to n, k^2 - 1 is a multiple of n.
    """
    if n < 2:
        return False, []

    units = [k for k in range(1, n) if math.gcd(k, n) == 1]

    results = {}
    all_success = True

    for k in units:
        check = (k**2 - 1) % n == 0
        results[k] = check
        if not check:
            all_success = False

    return all_success, results

N_to_test = [2, 3, 4, 5, 6, 7, 8, 10, 12]
test_results = {}

for n in N_to_test:
    success, details = check_n(n)
    test_results[n] = (success, details)

# Format results for writing to notes
note_content = []
for n, (success, details) in test_results.items():
    if success:
        note_content.append(f"N={n}: SUCCESS. For all units k, k^2 - 1 is divisible by {n}.")
    else:
        failing_k = next(k for k, check in details.items() if not check)
        note_content.append(f"N={n}: FAILURE. For k={failing_k}, k^2 - 1 = {failing_k**2 - 1}, and this is NOT divisible by {n} (remainder is {(failing_k**2 - 1) % n}).")

print("\\n".join(note_content))
